public class Main {
    public static void main(String[] args) {
        Cat 甲 = new Cat("{n1}");
        Cat 乙 = new Cat("{n2}");
        甲.朋友 = 乙;
        乙.朋友 = 甲;
        System.out.println("甲的朋友是：" + 甲.朋友.name);
        System.out.println("乙的朋友是：" + 乙.朋友.name);
        System.out.println("两位互相指着对方吗：" + (甲.朋友 == 乙 && 乙.朋友 == 甲));
    }
}

class Cat {
    String name;
    Cat 朋友;

    Cat(String name) {
        this.name = name;
    }
}
